// Writes src/playgrounds/registry.generated.tsx from the folders in src/playgrounds/.
// Runs automatically before dev, build, typecheck and check. Do not edit the output by hand.
import fs from "node:fs";
import path from "node:path";

const dir = path.join(process.cwd(), "src", "playgrounds");
const names = fs.readdirSync(dir, { withFileTypes: true })
  .filter((d) => d.isDirectory() && fs.existsSync(path.join(dir, d.name, "View.tsx")))
  .map((d) => d.name).sort();
const id = (n) => "P_" + n.replace(/[^a-zA-Z0-9]/g, "_");
const out = `// Generated by scripts/gen-registry.mjs. Do not edit.
"use client";
import type { ComponentType } from "react";
${names.map((n) => `import ${id(n)} from "./${n}/View";`).join("\n")}

export const REGISTRY: Record<string, ComponentType> = {
${names.map((n) => `  "${n}": ${id(n)},`).join("\n")}
};
`;
const file = path.join(dir, "registry.generated.tsx");
if (!fs.existsSync(file) || fs.readFileSync(file, "utf8") !== out) fs.writeFileSync(file, out);
